slideContent:
{
  "steps": [
    {
      "id": "step_01_open",
      "type": "narrator",
      "messages": [
        "Most people hold two versions of God.",
        "The one they'd describe if someone asked. And the one they actually feel when things fall apart.",
        "This is about the second one."
      ]
    },
    {
      "id": "step_02_felt_image",
      "type": "single_select",
      "question": "When you fail or struggle — what do you feel like God is doing?",
      "options": [
        {
          "id": "disappointed",
          "text": "He's disappointed in me"
        },
        {
          "id": "distant",
          "text": "He feels far away"
        },
        {
          "id": "watching",
          "text": "He's watching to see what I do"
        },
        {
          "id": "demanding",
          "text": "He expects more from me"
        },
        {
          "id": "silent",
          "text": "He goes quiet"
        },
        {
          "id": "patient",
          "text": "He's patient with me"
        },
        {
          "id": "close",
          "text": "He stays close"
        },
        {
          "id": "unsure",
          "text": "I honestly don't know"
        }
      ],
      "variable": "god_expectation",
      "branches": {
        "disappointed": [
          {
            "type": "narrator",
            "messages": [
              "When things fall apart, part of you braces for His disappointment."
            ]
          }
        ],
        "distant": [
          {
            "type": "narrator",
            "messages": [
              "When things fall apart, part of you feels like He steps back."
            ]
          }
        ],
        "watching": [
          {
            "type": "narrator",
            "messages": [
              "When things fall apart, part of you feels like He's just watching — waiting to see what you'll do."
            ]
          }
        ],
        "demanding": [
          {
            "type": "narrator",
            "messages": [
              "When things fall apart, part of you feels like He's keeping score."
            ]
          }
        ],
        "silent": [
          {
            "type": "narrator",
            "messages": [
              "When things fall apart, part of you feels like He goes quiet."
            ]
          }
        ],
        "patient": [
          {
            "type": "narrator",
            "messages": [
              "Even when things fall apart, something in you trusts that He's still with you."
            ]
          }
        ],
        "close": [
          {
            "type": "narrator",
            "messages": [
              "Even in it, part of you senses He doesn't leave."
            ]
          }
        ],
        "unsure": [
          {
            "type": "narrator",
            "messages": [
              "You're not quite sure what to expect from Him. That's an honest place to start."
            ]
          }
        ]
      }
    },
    {
      "id": "step_03_source_intro",
      "type": "narrator",
      "messages": [
        "That feeling came from somewhere. Let's see if we can find it."
      ]
    },
    {
      "id": "step_04_source",
      "type": "single_select",
      "question": "Where do you think it comes from most?",
      "options": [
        {
          "id": "parent",
          "text": "How a parent or caregiver loved me"
        },
        {
          "id": "church",
          "text": "What I absorbed from church"
        },
        {
          "id": "failure",
          "text": "Something I haven't forgiven myself for"
        },
        {
          "id": "silence",
          "text": "Prayers that felt unanswered"
        },
        {
          "id": "suffering",
          "text": "Something painful I never reconciled with God"
        },
        {
          "id": "unknown",
          "text": "I'm not sure. It's always just been there"
        }
      ],
      "variable": "wound_source",
      "branches": {
        "parent": [
          {
            "type": "narrator",
            "messages": [
              "How we're first loved tends to shape what we come to expect from love."
            ]
          }
        ],
        "church": [
          {
            "type": "narrator",
            "messages": [
              "What we're taught about God early can outlast what we actually believe later."
            ]
          }
        ],
        "failure": [
          {
            "type": "narrator",
            "messages": [
              "When we haven't forgiven ourselves, it's hard to believe someone else has."
            ]
          }
        ],
        "silence": [
          {
            "type": "narrator",
            "messages": [
              "Unanswered prayer changes what we let ourselves expect."
            ]
          }
        ],
        "suffering": [
          {
            "type": "narrator",
            "messages": [
              "When something painful was never resolved, it tends to stay in the room with God."
            ]
          }
        ],
        "unknown": [
          {
            "type": "narrator",
            "messages": [
              "Sometimes an image just forms slowly. No single moment. Just accumulation."
            ]
          }
        ]
      }
    },
    {
      "id": "step_05_pivot",
      "type": "narrator",
      "messages": [
        "Now think of a moment when you felt genuinely loved.",
        "A real one. A person. A place. Something you can picture."
      ]
    },
    {
      "id": "step_06_who",
      "type": "open_text",
      "question": "Who was there?",
      "variable": "moment_who",
      "required": true
    },
    {
      "id": "step_07_what",
      "type": "open_text",
      "question": "What happened?",
      "variable": "moment_what",
      "required": true
    },
    {
      "id": "step_08_felt_sense",
      "type": "open_text",
      "question": "What did that feel like from the inside? One or two words.",
      "variable": "felt_sense",
      "required": true
    },
    {
      "id": "step_09_qualities",
      "type": "single_select",
      "question": "What was most present in that moment?",
      "options": [
        {
          "id": "closeness",
          "text": "Closeness"
        },
        {
          "id": "patience",
          "text": "Patience"
        },
        {
          "id": "known",
          "text": "Being fully known"
        },
        {
          "id": "accepted",
          "text": "Being accepted as I am"
        },
        {
          "id": "delight",
          "text": "Someone delighting in me"
        },
        {
          "id": "safety",
          "text": "Safety"
        },
        {
          "id": "joy",
          "text": "Joy"
        },
        {
          "id": "peace",
          "text": "Peace"
        },
        {
          "id": "not_alone",
          "text": "Not being alone in it"
        }
      ],
      "variable": "love_quality"
    },
    {
      "id": "step_10_gap",
      "type": "narrator",
      "messages": [
        "You just meditated on a God who is love itself.",
        "And yet the image you've been carrying doesn't quite match that.",
        "Hold both of those things at the same time."
      ]
    },
    {
      "id": "step_11_gap_notice",
      "type": "single_select",
      "question": "When you do — what do you notice?",
      "options": [
        {
          "id": "sadness",
          "text": "Something like sadness"
        },
        {
          "id": "longing",
          "text": "I want it to be different"
        },
        {
          "id": "confusion",
          "text": "Confusion — I don't know what to do with it"
        },
        {
          "id": "numb",
          "text": "Not much. They feel separate"
        },
        {
          "id": "shifting",
          "text": "Something shifting — like it could be true"
        },
        {
          "id": "other",
          "text": "Something else"
        }
      ],
      "variable": "gap_reaction",
      "allow_other": true
    },
    {
      "id": "step_12_gap_locate",
      "type": "single_select",
      "question": "Which is closer to where you are right now?",
      "options": [
        {
          "id": "want_different",
          "text": "Part of me wants to believe He's different than I expect"
        },
        {
          "id": "head_not_heart",
          "text": "I believe it in my head, but I can't feel it"
        },
        {
          "id": "not_sure",
          "text": "I genuinely don't know"
        },
        {
          "id": "dont_think_so",
          "text": "I don't think He is different"
        }
      ],
      "variable": "gap_position",
      "branches": {
        "want_different": [
          {
            "type": "narrator",
            "messages": [
              "That want is worth paying attention to."
            ]
          }
        ],
        "head_not_heart": [
          {
            "type": "narrator",
            "messages": [
              "That distance between knowing and feeling is where most of this work lives."
            ]
          }
        ],
        "not_sure": [
          {
            "type": "narrator",
            "messages": [
              "Not knowing is an honest place to start."
            ]
          }
        ],
        "dont_think_so": [
          {
            "type": "narrator",
            "messages": [
              "That's honest. Stay with the question anyway."
            ]
          }
        ]
      }
    },
    {
      "id": "step_13_reframe",
      "type": "narrator",
      "messages": [
        "If God is love itself, He can't be less than the best love you've ever felt.",
        "He'd be where it came from."
      ]
    },
    {
      "id": "step_14_close",
      "type": "final",
      "messages": [
        "This week: when you feel genuinely loved by anyone, pause.",
        "Ask — is this what He is like?",
        "Let the moments answer."
      ]
    }
  ],
  "summaryTemplate": "When things fall apart, you feel like {god_expectation} — shaped most by {wound_source}. In a real moment of love, you felt {felt_sense}. When you held both together, you noticed {gap_reaction}."
}

{
  "title": "End of Week 1 Reflection",
  "description": "A check in to reflect on your well-being the last week in and out of this program.",
  "questions": [
    {
      "id": "q1775156924928",
      "type": "rating",
      "label": "On a scale of 1-5 with 1 being terrible, and 5 being amazing, how did your week go?"
    },
    {
      "id": "q1775156937661",
      "type": "text",
      "label": "What's something that you're grateful for this past week?"
    },
    {
      "id": "q1775156981594",
      "type": "text",
      "label": "What's something that you've struggled with this past week?"
    }
  ]
}

{
  "title": "End of Week 2 Reflection",
  "description": "",
  "questions": [
    {
      "id": "q1773694071419",
      "type": "rating",
      "label": "How do you think you are growing spiritually?"
    },
    {
      "id": "q1773694075880",
      "type": "single_select",
      "label": "Which topic impacted you the most this week?",
      "options": [
        "Examination of conscience",
        "The Cross of Jesus",
        "Christ’s sacrifice for our sins",
        "Salvation through Jesus Christ"
      ]
    },
    {
      "id": "q1773694123121",
      "type": "single_select",
      "label": "Did the examination of conscience help you recognize areas of your life that need healing or change?",
      "options": [
        "Yes, very clearly",
        "Somewhat",
        "Not really yet",
        "I’m not sure"
      ]
    },
    {
      "id": "q1773694140015",
      "type": "single_select",
      "label": "Have you been to the Sacrament of Reconciliation recently?",
      "options": [
        "Yes",
        "No"
      ]
    }
  ]
}

{
  "id": "forgiveness_guided_experience",
  "title": "Do You Want to Be Well?",
  "subtitle": "A guided experience through the terrain of forgiveness",
  "estimated_duration_minutes": 25,
  "steps": [
    {
      "id": "s1",
      "type": "narrator",
      "messages": [
        "Most people who struggle to forgive don't have a forgiveness problem.",
        "They have a misunderstanding problem.",
        "Forgiveness can feel like surrender — like letting someone off the hook. Like saying what happened didn't matter.",
        "That is not what forgiveness is.",
        "This experience is going to show you what it actually is — and walk you through it, at your own pace."
      ]
    },
    {
      "id": "s2",
      "type": "single_select",
      "question": "Are you willing to give this a try?",
      "variable": "readiness",
      "options": [
        {
          "id": "ready",
          "text": "I am ready and I want to do this"
        },
        {
          "id": "hesitant",
          "text": "I want to, but part of me is holding back"
        },
        {
          "id": "unsure",
          "text": "I am not sure I am willing yet"
        },
        {
          "id": "present",
          "text": "Someone is already in my mind"
        }
      ]
    },
    {
      "id": "s3",
      "type": "narrator",
      "messages": [
        "I appreciate your honesty.",
        "You don't need to be sure. You just need to be here.",
        "There is a moment in the gospel where Jesus finds a man who has been paralyzed for thirty-eight years, lying beside a healing pool.",
        "The first thing Jesus asks this person is not 'Do you believe?' — it's not 'Are you sorry?'",
        "Instead He asks: 'Do you want to be well?'",
        "Thirty-eight years is a long time to carry something.",
        "But the invitation to receive healing from Jesus always starts with the same fundamental question.",
        "Do you want to be well?"
      ]
    },
    {
      "id": "s4",
      "type": "narrator",
      "messages": [
        "— THE WOUND —",
        "Before you can release anything, you have to see what you are actually holding.",
        "Somewhere in your life there is a wound.",
        "Maybe one comes to mind immediately. Maybe several do.",
        "We are going to start with one — not the whole history, just one person or one moment."
      ]
    },
    {
      "id": "s5",
      "type": "single_select",
      "question": "Who or what comes to mind first?",
      "variable": "wound_source",
      "allow_other": true,
      "options": [
        {
          "id": "family",
          "text": "A parent or family member"
        },
        {
          "id": "partner",
          "text": "A partner or spouse"
        },
        {
          "id": "friend",
          "text": "A friend or community member"
        },
        {
          "id": "authority",
          "text": "A church leader or authority figure"
        },
        {
          "id": "self",
          "text": "Myself"
        },
        {
          "id": "god",
          "text": "God"
        }
      ]
    },
    {
      "id": "s6",
      "type": "open_text",
      "question": "You can name them here — a first name, a role, or just 'this person.' Or leave it blank. God already knows.",
      "variable": "person_name",
      "required": false
    },
    {
      "id": "s7",
      "type": "narrator",
      "messages": [
        "Anger gets a bad reputation.",
        "But Saint Thomas Aquinas taught that anger is actually a gift — a passion given to us to right what is wrong.",
        "Christ himself turned over tables in the temple. He was justly angry.",
        "The initial feeling of being hurt, of wanting the wrong corrected — that is not sin.",
        "That is a healthy soul responding to an injustice.",
        "The problem is not the anger. It is what happens to it.",
        "When it goes unnamed and unprocessed, it turns into resentment.",
        "And resentment is like drinking a little bit of poison every day — and hoping the other person dies."
      ]
    },
    {
      "id": "s8",
      "type": "open_text",
      "question": "What happened? Not the whole story — just the moment that still surfaces. Write as much or as little as you want.",
      "variable": "what_happened",
      "required": false
    },
    {
      "id": "s9",
      "type": "single_select",
      "question": "When it happened, how did it land in you?",
      "variable": "how_it_landed",
      "allow_other": true,
      "options": [
        {
          "id": "invisible",
          "text": "I felt like I didn't matter"
        },
        {
          "id": "unsafe",
          "text": "I felt unsafe"
        },
        {
          "id": "betrayed",
          "text": "I felt betrayed by someone I trusted"
        },
        {
          "id": "stolen",
          "text": "I felt like something was taken from me"
        },
        {
          "id": "abandoned",
          "text": "I felt abandoned"
        },
        {
          "id": "ashamed",
          "text": "I felt ashamed — like it was somehow my fault"
        },
        {
          "id": "shutdown",
          "text": "I shut down and went numb"
        }
      ]
    },
    {
      "id": "s10",
      "type": "narrator",
      "messages": [
        "Whatever you named — it was real.",
        "You are allowed to say that it mattered.",
        "Naming it honestly is not wallowing in it.",
        "It is the first step toward releasing it."
      ]
    },
    {
      "id": "s11",
      "type": "open_text",
      "question": "If you want, say more. What did it feel like to carry this?",
      "variable": "wound_words",
      "required": false
    },
    {
      "id": "s12",
      "type": "narrator",
      "messages": [
        "— WHAT IT HAS COST YOU —",
        "The wound happened once.",
        "But carrying it has had a daily price.",
        "Unforgiveness rarely announces itself.",
        "It shows up as tightness in the chest when their name comes up.",
        "As replaying what happened — rehearsing what you wish you had said.",
        "As walls you built to stay safe that also keep the good things out."
      ]
    },
    {
      "id": "s13",
      "type": "single_select",
      "question": "Looking honestly at your life — what has carrying this wound cost you most?",
      "variable": "what_it_cost",
      "allow_other": true,
      "options": [
        {
          "id": "peace",
          "text": "My peace"
        },
        {
          "id": "trust",
          "text": "My ability to trust people"
        },
        {
          "id": "god_relation",
          "text": "My relationship with God"
        },
        {
          "id": "identity",
          "text": "My sense of who I am"
        },
        {
          "id": "relationship",
          "text": "A relationship that could have been whole"
        },
        {
          "id": "time",
          "text": "Time — years lived under this weight"
        },
        {
          "id": "joy",
          "text": "My joy"
        }
      ]
    },
    {
      "id": "s14",
      "type": "open_text",
      "question": "Say more if you want — what has unforgiveness quietly been doing in your life?",
      "variable": "cost_words",
      "required": false
    },
    {
      "id": "s15",
      "type": "single_select",
      "question": "Beneath the wound, there is usually a sense that something is still owed. What does your heart feel is owed to you?",
      "variable": "still_owed",
      "allow_other": true,
      "options": [
        {
          "id": "apology",
          "text": "An apology — I want them to admit what they did"
        },
        {
          "id": "explanation",
          "text": "An explanation — I need to understand why"
        },
        {
          "id": "restoration",
          "text": "For things to be made right"
        },
        {
          "id": "justice",
          "text": "Justice — I want them to face what they did"
        },
        {
          "id": "unfinished",
          "text": "I don't know — something just feels unfinished"
        },
        {
          "id": "nothing",
          "text": "Nothing — I just can't seem to release it"
        }
      ]
    },
    {
      "id": "s16",
      "type": "narrator",
      "messages": [
        "You deserve all of those things.",
        "And here is the hard truth:",
        "You may never get them from this person.",
        "They may not be sorry. They may not even know the damage they caused.",
        "The question is not whether you deserve what is owed.",
        "The question is: who are you going to make the judge?"
      ]
    },
    {
      "id": "s17",
      "type": "narrator",
      "messages": [
        "— THE TURNING POINT —",
        "Saint Pope John Paul II wrote:",
        "'Forgiveness is the restoration of freedom to oneself. It is the key held in our own hand to our prison cell.'",
        "You are holding the key. Not to their prison. To yours.",
        "Forgiveness does not mean what they did was okay.",
        "It does not mean you trust them again.",
        "It does not require reconciliation — reconciliation takes two people willing to come back together. Forgiveness only requires one.",
        "It means you stop being the one who holds the debt.",
        "You hand that debt to God — the only truly just Judge — and you open your hand."
      ]
    },
    {
      "id": "s18",
      "type": "single_select",
      "question": "Right now, in this moment — are you willing to begin?",
      "variable": "forgiveness_decision",
      "options": [
        {
          "id": "yes",
          "text": "Yes — I am choosing this"
        },
        {
          "id": "partial",
          "text": "I want to, but part of me is still holding on"
        },
        {
          "id": "not_yet",
          "text": "I need God to make me willing first"
        },
        {
          "id": "hard",
          "text": "I don't know — this is harder than I expected"
        }
      ],
      "branches": {
        "yes": [
          {
            "id": "s18b_yes",
            "type": "narrator",
            "messages": [
              "Then let's not wait.",
              "Read this slowly. Say it aloud if you can.",
              "Insert the name — or just 'this person' — where you see the space.",
              "If your heart resists at any line, pause there and name the resistance to God. Then continue.",
              "—",
              "Lord Jesus Christ,",
              "I come before You with this wound.",
              "I name what happened — I do not minimize it, and I do not pretend it did not matter.",
              "It mattered. It cost me. And I have been carrying it.",
              "But I no longer want to be the judge of [this person].",
              "I hand that role back to You — the only just Judge.",
              "I choose, as an act of my will and not my feelings, to forgive.",
              "I release my claim to what is owed.",
              "I open my hand.",
              "I renounce every hold that bitterness, resentment, and unforgiveness have had over my heart.",
              "I close this door to the enemy.",
              "In the name of Jesus Christ, this wound no longer gives him a legal right in my life.",
              "Lord, heal what is still broken here.",
              "Pour Your peace into the space where the wound was.",
              "Amen."
            ]
          }
        ],
        "partial": [
          {
            "id": "s18b_partial",
            "type": "narrator",
            "messages": [
              "A half-open hand is still a hand beginning to open. That is enough.",
              "Read this slowly. Say it aloud if you can.",
              "—",
              "Lord Jesus Christ,",
              "I come before You with this wound.",
              "I name what happened — I do not minimize it, and I do not pretend it did not matter.",
              "It mattered. It cost me. And I have been carrying it.",
              "But I no longer want to be the judge of [this person].",
              "I hand that role back to You — the only just Judge.",
              "I choose, as an act of my will and not my feelings, to forgive.",
              "I release my claim to what is owed.",
              "I open my hand — even the part that is still holding on.",
              "I renounce every hold that bitterness and unforgiveness have had over my heart.",
              "I close this door to the enemy.",
              "In the name of Jesus Christ, this wound no longer gives him a legal right in my life.",
              "Lord, heal what is still broken here.",
              "And help me to mean this more tomorrow than I do today.",
              "Amen."
            ]
          }
        ],
        "not_yet": [
          {
            "id": "s18b_notyet",
            "type": "narrator",
            "messages": [
              "That honesty is exactly where God can work.",
              "You don't need to manufacture a willingness you don't have.",
              "Read this slowly. Say it aloud if you can.",
              "—",
              "Lord Jesus Christ,",
              "I cannot get there on my own.",
              "I am not willing — or I don't know if I am.",
              "But I am here. I am asking.",
              "Give me the willingness to be willing.",
              "Start there, if that is all You have to work with today.",
              "I do not want to carry this anymore.",
              "Even if I cannot fully release it today,",
              "I am opening the door and asking You to come in.",
              "I trust that what You begin, You will finish.",
              "Amen."
            ]
          }
        ],
        "hard": [
          {
            "id": "s18b_hard",
            "type": "narrator",
            "messages": [
              "The hardest forgiveness is often the deepest. Don't stop here.",
              "You don't need to manufacture a willingness you don't have.",
              "Read this slowly. Say it aloud if you can.",
              "—",
              "Lord Jesus Christ,",
              "I cannot get there on my own.",
              "I am not willing — or I don't know if I am.",
              "But I am here. I am asking.",
              "Give me the willingness to be willing.",
              "Start there, if that is all You have to work with today.",
              "I do not want to carry this anymore.",
              "Even if I cannot fully release it today,",
              "I am opening the door and asking You to come in.",
              "I trust that what You begin, You will finish.",
              "Amen."
            ]
          }
        ]
      }
    },
    {
      "id": "s19",
      "type": "open_text",
      "question": "After sitting with that prayer — what is present in you right now? Peace, resistance, grief, numbness, something shifting. Anything at all.",
      "variable": "after_prayer_response",
      "required": false
    },
    {
      "id": "s20",
      "type": "dynamic_reflection",
      "template": "You said: '{after_prayer_response}' — that response is worth staying with. Whatever is there is real, and God is already working in it."
    },
    {
      "id": "s21",
      "type": "narrator",
      "messages": [
        "— THE OTHER DIRECTION —",
        "Forgiveness runs two ways.",
        "You have been the one who was hurt.",
        "But you have also been the one who has hurt.",
        "Not as an accusation — as an invitation.",
        "The same mercy that is freeing you from what was done to you is available to the people you have wounded.",
        "And receiving God's mercy — deeply, personally, for yourself — is what makes it possible to extend it."
      ]
    },
    {
      "id": "s22",
      "type": "single_select",
      "question": "Is there someone in your life you know you have wounded — someone who may need your apology or repair?",
      "variable": "also_need_mercy",
      "options": [
        {
          "id": "yes",
          "text": "Yes — someone comes to mind"
        },
        {
          "id": "maybe",
          "text": "Possibly — I need to think about it"
        },
        {
          "id": "no",
          "text": "Not that I can think of right now"
        }
      ]
    },
    {
      "id": "s23",
      "type": "open_text",
      "question": "If someone comes to mind, name what happened here. You don't need to know what to do about it yet — just bring it into the light.",
      "variable": "repair_reflection",
      "required": false
    },
    {
      "id": "s24",
      "type": "narrator",
      "messages": [
        "One more thing before we close.",
        "The person who hurt you did not wound you from wholeness.",
        "They wounded you from their own brokenness.",
        "Hurt people hurt people.",
        "That does not excuse what they did.",
        "But understanding it can loosen the grip.",
        "They are also someone Jesus is asking: 'Do you want to be well?'"
      ]
    },
    {
      "id": "s25",
      "type": "narrator",
      "messages": [
        "— THE ONGOING WORK —",
        "This is not a one-time event.",
        "Tomorrow, the same feeling may resurface. The same face may come back.",
        "That is not a sign that forgiveness didn't happen.",
        "It is a sign that healing goes in layers.",
        "Think of it like tending a garden.",
        "You plant a seed, you water it, you come back.",
        "Weeds return — and you pull them again.",
        "What you did here today was plant a seed.",
        "Each time you choose forgiveness again, you are weakening the enemy's hold and allowing healing to go deeper."
      ]
    },
    {
      "id": "s26",
      "type": "single_select",
      "question": "As you prepare for the deliverance prayers ahead — what are you committing to in this area?",
      "variable": "commitment_level",
      "allow_other": true,
      "options": [
        {
          "id": "return_prayer",
          "text": "I will return to this prayer every time the wound resurfaces"
        },
        {
          "id": "seek_support",
          "text": "I will bring this wound to a counselor or trusted person"
        },
        {
          "id": "daily_choice",
          "text": "I will speak this forgiveness aloud each morning until my heart catches up"
        },
        {
          "id": "sacrament",
          "text": "I will bring this to confession or spiritual direction"
        }
      ]
    },
    {
      "id": "s27",
      "type": "open_text",
      "question": "Put your commitment in your own words. A commitment made specific is a commitment made real.",
      "variable": "commitment_words",
      "required": false
    },
    {
      "id": "s28",
      "type": "dynamic_reflection",
      "template": "You are committing to: '{commitment_words}' — God heard that."
    },
    {
      "id": "s29",
      "type": "open_text",
      "question": "Before you go — what is one truth you want to carry with you from this experience? Not a task. Just a truth.",
      "variable": "closing_reflection",
      "required": false
    },
    {
      "id": "s30",
      "type": "final",
      "messages": [
        "Father,",
        "Thank You that You forgave me first.",
        "While I was still in my sin — still holding onto my own brokenness — You chose me.",
        "Give me that same heart for the person I have been carrying.",
        "Heal the wound that made forgiveness feel impossible.",
        "Close every door that unforgiveness has opened in my life.",
        "Prepare me for the freedom that is coming.",
        "Amen.",
        "—",
        "The freedom ahead of you is real.",
        "The enemy has used this wound as a foothold long enough.",
        "This act of forgiveness is not just inner healing — it is warfare.",
        "You are taking back ground.",
        "Keep going."
      ]
    }
  ],
  "summaryTemplate": "This experience focused on a wound involving {wound_source} — {person_name}. What happened: {what_happened}. It landed as {how_it_landed} — {wound_words}. The greatest cost: {what_it_cost} — {cost_words}. What still felt owed: {still_owed}. Forgiveness decision: {forgiveness_decision}. After the prayer: {after_prayer_response}. Need to repair with others: {also_need_mercy} — {repair_reflection}. Commitment: {commitment_level} — {commitment_words}. Truth to carry: {closing_reflection}."
}

